import{_ as e,o as s,c as n,a3 as r}from"./chunks/framework.Cj_fzHAr.js";const t="/manual/img/encuestas/mis-encuestas.png",o="/manual/img/encuestas/nueva-encuesta.png",h=JSON.parse('{"title":"Encuestas","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/encuestas.md","filePath":"modulos/encuestas.md"}'),u={name:"modulos/encuestas.md"};function i(l,a,c,d,g,p){return s(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="encuestas" tabindex="-1">Encuestas <a class="header-anchor" href="#encuestas" aria-label="Permalink to &quot;Encuestas&quot;">​</a></h1><p>El módulo de <strong>Encuestas</strong> te permite consultar a los trabajadores de forma rápida y dejar registro de sus respuestas. Sirve para muchas cosas: encuestas de clima de seguridad, verificación de comprensión tras una capacitación, levantamiento de condiciones inseguras o cualquier consulta que quieras documentar.</p><p>Hay dos miradas del módulo, según tu rol:</p><ul><li>Como <strong>trabajador</strong>, ves <strong>las encuestas que te asignaron</strong> y las respondes.</li><li>Como <strong>gestor</strong>, <strong>creas encuestas</strong>, eliges a quién van dirigidas y revisas los resultados.</li></ul><h2 id="responder-una-encuesta-trabajador" tabindex="-1">Responder una encuesta (trabajador) <a class="header-anchor" href="#responder-una-encuesta-trabajador" aria-label="Permalink to &quot;Responder una encuesta (trabajador)&quot;">​</a></h2><ol><li>En el menú lateral, entra a <strong>Encuestas</strong>.</li><li>En la sección <strong>&quot;Mis encuestas&quot;</strong> verás las que tienes asignadas. Si no hay ninguna, aparecerá <em>&quot;No tienes encuestas asignadas por ahora&quot;</em>.</li><li>Abre la encuesta, responde cada pregunta (en las preguntas abiertas, usa el campo <em>&quot;Comparte tu respuesta&quot;</em>) y envíala.</li></ol><p><img src="'+t+'" alt="Sección Mis encuestas con el seguimiento personal del trabajador"></p><blockquote><p>💡 Las encuestas que te asignan también aparecen como pendiente en tu <a href="/manual/modulos/dashboard.html">Dashboard</a> y tu <a href="/manual/modulos/bandeja-entrada.html">Bandeja de Entrada</a>.</p></blockquote><h2 id="crear-una-encuesta-gestor" tabindex="-1">Crear una encuesta (gestor) <a class="header-anchor" href="#crear-una-encuesta-gestor" aria-label="Permalink to &quot;Crear una encuesta (gestor)&quot;">​</a></h2><ol><li>Entra a <strong>Encuestas</strong> y haz clic en <strong>Nueva Encuesta</strong>.</li><li>El asistente te guía por pasos: <ul><li><strong>Paso 1 · Información general</strong> — escribe el <strong>Título</strong> <em>(obligatorio)</em> y una <strong>Descripción</strong> <em>(opcional)</em> con el objetivo o la duración estimada.</li><li><strong>Paso 2 · Audiencia destino</strong> — elige el <strong>Cargo destino</strong> <em>(obligatorio)</em>: a qué cargos o trabajadores se enviará la encuesta.</li><li>Agrega las <strong>preguntas</strong> que quieras hacer.</li></ul></li><li>Crea la encuesta. Cada destinatario la recibirá como pendiente de responder.</li></ol><p><img src="'+o+'" alt="Asistente de Nueva Encuesta con los pasos de información y audiencia"></p><h2 id="revisar-resultados" tabindex="-1">Revisar resultados <a class="header-anchor" href="#revisar-resultados" aria-label="Permalink to &quot;Revisar resultados&quot;">​</a></h2><p>En la vista de gestión verás un resumen con indicadores:</p><ul><li><strong>Encuestas creadas</strong> — cuántas has lanzado.</li><li><strong>Trabajadores alcanzados</strong> — a cuántas personas llegaron.</li><li><strong>Tasa de respuesta</strong> — qué porcentaje ya respondió.</li></ul><p>Cada encuesta de la lista muestra cuántas <strong>Preguntas</strong> tiene, cuántos <strong>Destinatarios</strong> y cuántas respuestas <strong>Respondidas</strong> lleva. Puedes usar el filtro <strong>&quot;Mostrar&quot;</strong> para ver solo las tuyas o todas, y el buscador <strong>&quot;Buscar encuestas…&quot;</strong> para encontrar una específica.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Quién puede crear encuestas?</strong> Los roles de gestión (Administrador, Prevencionista, Jefe de Obra). Un trabajador solo responde las que le asignan. Consulta <a href="/manual/roles/">Roles de Usuario</a>.</p><p><strong>Asigné la encuesta pero nadie responde.</strong> Los destinatarios la verán en su sección &quot;Mis encuestas&quot;, en su Dashboard y en su Bandeja de Entrada. Si la <strong>tasa de respuesta</strong> está baja, puedes recordarles por la <a href="/manual/modulos/bandeja-entrada.html">Bandeja de Entrada</a>.</p><p><strong>¿Puedo dirigir una encuesta solo a ciertos cargos?</strong> Sí. En el <strong>Paso 2 · Audiencia destino</strong> eliges el cargo destino, de modo que la encuesta llega solo a las personas que cumplen ese cargo.</p><p><strong>¿Las respuestas son anónimas?</strong> Las respuestas quedan asociadas para poder dar seguimiento al cumplimiento (saber quién respondió). Si necesitas una consulta anónima, indícalo en la descripción y maneja las preguntas en consecuencia.</p><p><strong>¿Una encuesta puede cerrar un ítem de capacitación?</strong> Sí. Cuando una encuesta está vinculada a un ítem de onboarding de un trabajador, responderla puede dar por cumplido ese ítem. Lo verás reflejado en la ficha de la obra.</p>',21)])])}const b=e(u,[["render",i]]);export{h as __pageData,b as default};
